const n_tau = PI * 2;
const n_height = 100;
const n_its_layer = 120;
// A regular polygon: with 3 corners a triangle.
const n_its_corner = 444;
// How far its corners are from the axis, on the bottom and on the
// top layer. Between them it shrinks linearly.
const n_radius_bottom = 35;
const n_radius_top = 35;
// How far it turns one way on its way up, linearly: 1 is a turn.
const n_twist = 0;
// Layer 1 is this far above the thread's ring, so the straight
// walls from the round ring to the triangle stand steep enough.
const n_height_cone = 12;

function f_o_p(n_it_layer_nor, n_it_corner_nor) {


    let n_tau    = Math.PI * 2;
    let n_blades = 12;      // number of blades (periods)
    let n_R0     = 10;     // base radius (centre of the blades)
    let n_k      = 10;      // blade length (radial)
    let n_bend   = 0.3;    // how much the angle folds back -> hook strength

    let n_ang = n_it_corner_nor;
    // n_ang is 0.0 .. 1.0
    let n_p = n_ang * n_blades;                               // 0 .. n_blades

    // your flat curve: h = left->right, w = up/down
    let n_h = n_p - n_bend * Math.sin(n_p * n_tau) ** 2;      // like v*x - sin(2πx)^2
    let n_w = Math.cos(n_p * n_tau);                          // -1 .. 1

    // wrap: horizontal -> angle, vertical -> radius
    let n_theta = n_h / n_blades;                             // back to 0 .. 1
    let n_r     = n_radius_bottom+n_R0 + n_k * n_w;                           // the "amplitude", now varying

    return {
        n_x: Math.sin(n_theta * n_tau) * n_r,
        n_y: Math.cos(n_theta * n_tau) * n_r,
        n_z: o_thread.n_z + n_height_cone + n_it_layer_nor * n_height,
    };
}

return {
    n_its_layer, n_its_corner, f_o_p
};
